  styles:[],
})
export class Sidebar {
  auth = inject(AuthService);
  get tituloPanel(): string {
    const rol = this.auth.session()?.rol;
    return rol === "DOCTOR"
      ? "PANEL MÉDICO"
      : rol === "RECEPCIONISTA"
        ? "RECEPCIÓN"
        : rol === "CAJERA"
          ? "CAJA"
          : rol === "TESORERA"
            ? "TESORERÍA"
            : "PANEL DE ADMINISTRACIÓN";
  }
  get esDoctor() {
    return this.auth.session()?.rol === "DOCTOR";
  }
  get menu() {
    const autenticado = this.auth.estaAutenticado();
    if (autenticado && this.esDoctor) {
      return FEATURE_NAVIGATION.atencion
        .filter((link) => this.auth.tienePermiso(link.permiso))
        .map((link) => ({
          ...link,
          icon: link.path === "/doctor" ? "ICON_MENU.png" : "ICON_DOCTORES.png",
        }));
    }
    return MENU.filter(
      (item) =>
        autenticado && (!item.permiso || this.auth.tienePermiso(item.permiso)),
    ).map((item) =>
      this.auth.session()?.rol === "CAJERA" && item.path === "/citas"
        ? { ...item, label: "Cobros y citas" }
        : item,
    );
  }
}

import { Permiso, Rol } from "../auth/auth.model";
import { PERMISOS_POR_ROL } from "./permisos";
export interface MenuItem {
  path: string;
  label: string;
  icon: string;
  roles: Rol[];
  permiso?: Permiso;
}
function item(
  path: string,
  label: string,
  icon: string,
  permiso?: Permiso,
): MenuItem {
  return {
    path,
    label,
    icon,
    permiso,
    roles: (Object.keys(PERMISOS_POR_ROL) as Rol[]).filter(
      (rol) => !permiso || PERMISOS_POR_ROL[rol].includes(permiso),
    ),
  };
}
export const MENU: MenuItem[] = [
  item("/home", "Inicio", "ICON_MENU.png"),
  item("/pacientes", "Pacientes", "ICON_PACIENTES.png", "PACIENTES_LEER"),
