import { ChangeDetectorRef, Component, inject } from "@angular/core";
import {
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from "@angular/forms";
import { ActivatedRoute, Router, RouterLink } from "@angular/router";
import { AuthService } from "../../../../core/auth/auth-service";
import { errorText } from "../../../../core/utils/http-error";
import { INICIO_POR_ROL } from "../../../../core/config/permisos";
import { returnUrlSeguro } from "../../../../core/utils/return-url";

@Component({
  standalone: true,
  imports: [ReactiveFormsModule, RouterLink],
  template:"<main class=\"contenedor-login\">\n  <section class=\"zona-imagen\">\n    <a routerLink=\"/home\" class=\"boton-regresar\"\n      ><span class=\"circulo-flecha\">←</span><span>Regresar</span></a\n    ><img\n      src=\"/img/FONDO LOGIN.png\"\n      alt=\"Consultorio médico\"\n      class=\"imagen-consultorio\"\n    />\n  </section>\n  <div class=\"separador-azul\"></div>\n  <section class=\"zona-formulario\">\n    <div class=\"contenido-formulario\">\n      <img\n        src=\"/img/LOGO GRANDE.png\"\n        alt=\"Logo Karely's\"\n        class=\"logo-karelys\"\n      />\n      <h1>INICIAR SESIÓN</h1>\n      <p class=\"texto-ayuda\">\n        Ingrese sus credenciales para acceder al sistema\n      </p>\n      @if(aviso){\n      <p class=\"mensaje-error\" role=\"status\">{{aviso}}</p>\n      }\n      <form\n        class=\"formulario-login\"\n        [formGroup]=\"loginForm\"\n        (ngSubmit)=\"login()\"\n      >\n        <label for=\"login-usuario\" class=\"etiqueta-accesible\">Usuario</label>\n        <input\n          id=\"login-usuario\"\n          name=\"username\"\n          formControlName=\"username\"\n          placeholder=\"Ingrese su usuario\"\n          required\n          autocomplete=\"username\"\n        />\n        <div class=\"caja-contrasena\">\n          <label for=\"login-contrasena\" class=\"etiqueta-accesible\">Contraseña</label>\n          <input\n            id=\"login-contrasena\"\n            [type]=\"mostrar?'text':'password'\"\n            name=\"password\"\n            formControlName=\"password\"\n            placeholder=\"Contraseña\"\n            required\n            autocomplete=\"current-password\"\n          /><button\n            type=\"button\"\n            class=\"boton-ojo\"\n            [attr.aria-label]=\"mostrar ? 'Ocultar contraseña' : 'Mostrar contraseña'\"\n            (click)=\"mostrar=!mostrar\"\n          >\n            ◉\n          </button>\n        </div>\n        @if(error){\n        <p class=\"mensaje-error\" role=\"alert\">{{error}}</p>\n        }\n        <button class=\"boton-ingresar\" type=\"submit\" [disabled]=\"loading\">\n          {{loading?'Ingresando...':'Iniciar Sesión'}}\n        </button>\n      </form>\n      <a class=\"enlace-recuperacion\" routerLink=\"/recuperar-password\"\n        >Olvidé mi contraseña</a\n      >\n    </div>\n  </section>\n</main>\n",
  styles:[],
})
export class LoginComponent {
  private readonly changeDetector = inject(ChangeDetectorRef);

  auth = inject(AuthService);
  router = inject(Router);
  route = inject(ActivatedRoute, { optional: true });
  aviso =
    this.route?.snapshot.queryParamMap.get("sesionExpirada") === "1"
      ? "Tu sesión ha vencido. Inicia sesión nuevamente."
      : "";
  mostrar = false;
  error = "";
  loading = false;
  readonly loginForm = new FormGroup({
    username: new FormControl("", {
      nonNullable: true,
      validators: [Validators.required],
    }),
    password: new FormControl("", {
      nonNullable: true,
      validators: [Validators.required],
    }),
  });
  async login() {
    try {
      if (this.loading) return;
      if (this.loginForm.invalid) {
        this.loginForm.markAllAsTouched();
        this.error = "Introduce tu usuario y contraseña";
        return;
      }
      this.error = "";
      this.loading = true;
      try {
        const { username, password } = this.loginForm.getRawValue();
        const s = await this.auth.login(username, password);
        const destino = returnUrlSeguro(
          this.route?.snapshot.queryParamMap.get("returnUrl"),
        );
        const destinoMedico =
          destino &&
          /^\/doctor(?:\/(?:horarios|consultas))?(?:[?#]|$)/.test(destino)
            ? destino
            : "/doctor";
        await this.router.navigateByUrl(
          s.rol === "DOCTOR"
            ? destinoMedico
            : (destino ?? INICIO_POR_ROL[s.rol]),
        );
      } catch (e) {
        this.error = errorText(e);
      } finally {
        this.loading = false;
      }
    } finally {
      this.changeDetector.markForCheck();
    }
  }
}

import type { FormGroup } from "@angular/forms";

const fieldLabels: Record<string, string> = {
  tipoDocumento: "Tipo de documento",
  numeroDocumento: "Número de documento",
  nombres: "Nombres",
  apellidos: "Apellidos",
  telefono: "Teléfono",
  correo: "Correo",
  direccion: "Dirección",
  estado: "Estado",
  fechaNacimiento: "Fecha de nacimiento",
  username: "Usuario",
  idRol: "Rol",
};

export function formErrorText(form: FormGroup): string {
  const messages = Object.entries(form.controls)
    .filter(([, control]) => control.invalid)
    .map(([field, control]) => {
      const label = fieldLabels[field] || field;
      if (control.hasError("required")) return `${label}: completa este campo`;
      if (control.hasError("email"))
        return `${label}: ingresa un correo válido`;
      if (control.hasError("maxlength"))
        return `${label}: máximo ${control.getError("maxlength").requiredLength} caracteres`;
      if (control.hasError("fechaFutura"))
        return `${label}: no puede ser futura`;
      return `${label}: revisa el valor ingresado`;
    });
  return messages[0] || "Revisa los datos del formulario.";
}

export function errorText(error: unknown): string {
  const value = error as {
    status?: number;
    error?: {
      error?: string;
      detail?: string;
      message?: string;
      validationErrors?: Record<string, string>;
    };
    message?: string;
  } | null;
  if (value?.status === 0)
    return "No se pudo conectar con el sistema. Revisa tu conexión e inténtalo de nuevo.";
  if (value?.status && value.status >= 500)
    return "No se pudo completar la operación. Inténtalo de nuevo en unos minutos.";
  const fields = value?.error?.validationErrors;
  if (fields && Object.keys(fields).length) {
    const message = Object.values(fields).find(
      (text) => typeof text === "string" && text.trim(),
    );
    return mensajeClaro(message || "Revisa los datos del formulario.");
  }
  const message =
    value?.error?.message ||
    value?.error?.detail ||
    value?.error?.error ||
    value?.message ||
    "No se pudo completar la operación.";
  if (value?.status === 403)
    return "Tu cuenta no tiene permiso para realizar esta acción.";
  if (value?.status === 401)
    return /credenciales|contraseña|password/i.test(message)
      ? "Usuario o contraseña incorrectos."
      : "Tu sesión no es válida. Vuelve a iniciar sesión.";
  return mensajeClaro(message);
}

function mensajeClaro(message: string): string {
  if (typeof message !== "string") return "No se pudo completar la operación.";
  let text = message
    .replace(/\u00c3\u00b3/g, "ó")
    .replace(/\u00c3\u00a1/g, "á")
    .replace(/\u00c3\u00a9/g, "é")
    .replace(/\u00c3\u00ad/g, "í")
    .replace(/\u00c3\u00ba/g, "ú")
    .replace(/\u00c3\u00b1/g, "ñ");
  text = text
    .split(/\r?\n/)[0]
    .replace(/^\s*ORA-20\d{3}:\s*/, "")
    .trim();
  if (
    /ORA-\d|SQL(?:Exception|STATE)|\bSELECT\b.+\bFROM\b|constraint|Http failure|https?:\/\/|\b(?:TypeError|NullPointerException|Bad Request|Internal Server Error|Unauthorized|Forbidden)\b/i.test(
      text,
    )
  )
    return "No se pudo completar la operación. Inténtalo de nuevo.";
  if (
    /must (?:not|be|match)|size must|length must|not a well-formed/i.test(text)
  )
    return "Revisa los datos ingresados y completa los campos obligatorios.";
  return text || "No se pudo completar la operación.";
}
